    if (str == null || suffix == null) {
        return (str == null) && (suffix == null);
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    if (suffix.isEmpty()) {
        return true;
    }
    if (ignoreCase) {
        str = str.toUpperCase(java.util.Locale.ENGLISH);
        suffix = suffix.toUpperCase(java.util.Locale.ENGLISH);
    }
    return str.endsWith(suffix);
}

