@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type.equals(Character.class) || type.equals(char.class)) {
        if (value instanceof Integer) {
            return (char) (Integer) value;
        }
        if (value instanceof Long) {
            return (char) (Long) value;
        }
        if (value instanceof Double) {
            return (char) (Double) value;
        }
        if (value instanceof Float) {
            return (char) (Float) value;
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            } else {
                throw new Exception("Cannot convert string of length " + str.length() + " to Character: " + value);
            }
        }
        if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        }
    }
    throw new Exception("Cannot convert " + value.getClass().getName() + " to " + type.getName());
}

