GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Get the first node from the tour
    Set<V> nodes = graph.nodes();
    if (nodes.isEmpty()) {
        throw new IllegalArgumentException("No nodes in the graph");
    }

    // Get a node to start with - I will pick one that is connected by an edge in the tour
    V currentNode = nodes.iterator().next();

    // Find a node that is connected by an edge in our tour
    for (V node : nodes) {
        if (tour.stream().anyMatch(e -> e.incident(node))) {
            currentNode = node;
            break;
        }
    }

    // Build the path
    GraphPath<V, E> path = new SimpleDirectedGraph.SimpleWalk<>(graph, null, currentNode);

    // Get sorted edges to build the path
    List<E> edgeList = new ArrayList<>(tour);

    for (E edge : edgeList) {
        V start = edge.getGraph().getEdgeSource(edge);
        V end = edge.getGraph().getEdgeTarget(edge);

        V nextNode;
        if (start.equals(currentNode)) {
            nextNode = end;
        } else if (end.equals(currentNode)) {
            nextNode = start;
        } else {
            // The edge does not connect to the current node, skip or handle error
            continue;
        }

        path = path.appendEdge(graph, edge, nextNode);
        currentNode = nextNode;
    }

    return path;
}

