private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds.size() == 0) {
        return new Pair<List<Integer>,Long>(new ArrayList<Integer>(), 0L);
    }
    List<Integer> suffixSum = new ArrayList<Integer>(bounds.size());
    long total = 0;
    int sum = bounds.get(bounds.size() - 1);
    suffixSum.add(sum);
    for (int i = bounds.size() - 2; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }
    Collections.reverse(suffixSum);
    total = suffixSum.get(0);
    return new Pair<List<Integer>,Long>(suffixSum, total);
}

