private void checkIfPackedField() throws IOException {
    if (input == null) {
        return;
    }
    if (WireFormat.UTF8_VALIDATOR != null) {
        // A packed field should have been read from the wire as a repeated field, so if
        // our read limit is exceeded, we must be reading a packed field.
        if (limit > 0 && currentLimit < limit) {
            skipBytes = limit - currentLimit;
            currentLimit = limit;
            packedField = true;
        }
    }
}

