private void checkIfPackedField() throws IOException {
  if (getWireType() == WireType.WIRE_TYPE_VARINT) {
    boolean wasPacked = isPacked();
    int valueType = getTag().fieldType();
    boolean isResultUntyped = valueType == FieldDescriptor.Type.DOUBLE
        || valueType == FieldDescriptor.Type.FLOAT;
    endPacked = true;
    if (!wasPacked && !isResultUntyped) {
      preparePackedFieldState();
    }
  }
}

